#### 3. 对照与边界测试草案

```javascript
import assert from 'node:assert/strict';
import { buildPlayfulExpressionBlock } from './social-expression.mjs';

// 1. 字符长度边界检查（500 ~ 850 字符）
const partText = '你的参与度风格：普通群友。能接的话题就接，插不上就安静看；不抢话也不故意隐身。';
const block = buildPlayfulExpressionBlock(partText);
assert(block.length >= 500 && block.length <= 850, `Length out of bounds: ${block.length}`);

// 2. 关键意图与红线核对
assert(block.includes('草'), '必须包含“草”字规范声明');
assert(block.includes('不拿拟声、万能反问和“草”字填空'), '确保禁止将草作为口癖/填充');
assert(block.includes('反弹'), '包含正向反弹示例');
assert(block.includes('认真帮忙'), '遇到认真任务立即收敛');

// 3. 非群聊/关闭状态隔离
// 验证 prompt.js 在 isPrivate=true 或 expressionProfile='legacy' 时决不输出该 block。
```

