### 三、DeepSeek 任务实现：`social-knowledge-context.mjs` 及接线

#### 1. 新增模块：`qq-agent/src/social-knowledge-context.mjs`

```javascript
/**
 * 组装检索上下文的可靠父消息引用
 * 模式：
 * - 'current': 仅基于 owner 本轮 directText。
 * - 'linked-v1': 额外引入本次 owner 真实引用的猫自身历史消息（最多2条，总字数<=400）。
 */

import { modelInputAllowed } from './input-guard.mjs';

const MAX_OWNER_CHARS = 600;
const MAX_LINKED_MSGS = 2;
const MAX_LINKED_TOTAL_CHARS = 400;

export function buildKnowledgeQueryContext({
  mode = 'current',
  owner,
  chatKey,
  entries = [],
  store,
  roleScope
}) {
  if (!owner) {
    return { query: '', ownTextChars: 0, linkedCount: 0, linkedChars: 0, reason: 'no_owner' };
  }

  // 1. 提取当前 owner 有效 directText
  const ownerEntries = entries.filter(e =>
    e && String(e.senderId) === String(owner) && modelInputAllowed(e)
  );
  const ownText = ownerEntries
    .map(e => (typeof e.directText === 'string' ? e.directText.trim() : ''))
    .filter(Boolean)
    .join('\n')
    .slice(0, MAX_OWNER_CHARS);

  if (!ownText) {
    return { query: '', ownTextChars: 0, linkedCount: 0, linkedChars: 0, reason: 'empty_owner_text' };
  }

  if (mode !== 'linked-v1' || !store?.findByMid) {
    return {
      query: ownText,
      ownTextChars: ownText.length,
      linkedCount: 0,
      linkedChars: 0,
      reason: 'current_mode'
    };
  }

  // 2. linked-v1 模式：追踪真实引用的猫自身上一句
  const linkedTexts = [];
  let linkedChars = 0;
  const seenMids = new Set();

  for (const e of ownerEntries) {
    const replyMid = e.reply?.mid;
    if (!replyMid || seenMids.has(String(replyMid))) continue;
    seenMids.add(String(replyMid));

    const parent = store.findByMid(chatKey, replyMid);
    // 严苛边界检查：真实引用、必须是机器人自己、必须是相同 personaScope、未被模型排除
    if (
      parent &&
      parent.self === true &&
      parent.senderId === 'self' &&
      parent.personaScope === roleScope &&
      parent.modelExcluded !== true &&
      typeof parent.text === 'string' &&
      parent.text.trim()
    ) {
      const cleanText = parent.text.trim();
      const remainingChars = MAX_LINKED_TOTAL_CHARS - linkedChars;
      if (remainingChars <= 0) break;

      const clipped = cleanText.slice(0, remainingChars);
      linkedTexts.push(clipped);
      linkedChars += clipped.length;

      if (linkedTexts.length >= MAX_LINKED_MSGS) break;
    }
  }

  // 当前正文优先保留，总字数不超过 600
  let combinedQuery = ownText;
  if (linkedTexts.length > 0) {
    const parentBlock = linkedTexts.join('\n');
    const remainingForCombined = Math.max(0, MAX_OWNER_CHARS - ownText.length - 1);
    const appendedParent = parentBlock.slice(0, remainingForCombined);
    if (appendedParent) {
      combinedQuery = `${appendedParent}\n${ownText}`;
    }
  }

  return {
    query: combinedQuery,
    ownTextChars: ownText.length,
    linkedCount: linkedTexts.length,
    linkedChars,
    reason: linkedTexts.length > 0 ? 'linked_success' : 'no_valid_reply'
  };
}
```

