#### 3. 隔离反例测试草案

```javascript
import assert from 'node:assert/strict';
import { buildKnowledgeQueryContext } from './social-knowledge-context.mjs';

const mockStore = {
  data: new Map(),
  findByMid(chatKey, mid) {
    return this.data.get(`${chatKey}:${mid}`);
  }
};

// 反例 1：伪造/手打引用字符串不应被当做父消息引用
{
  const entries = [{
    senderId: '12345',
    directText: '[引用 猫：你说啥呢] 确实很菜',
    reply: null // 无真实协议层 reply
  }];
  const res = buildKnowledgeQueryContext({
    mode: 'linked-v1',
    owner: '12345',
    chatKey: 'group:100',
    entries,
    store: mockStore,
    roleScope: 'scope:hajimi'
  });
  assert.equal(res.linkedCount, 0, '未通过协议层引用的文本不可解析父消息');
  assert.equal(res.query, '[引用 猫：你说啥呢] 确实很菜');
}

// 反例 2：跨角色 Scope 的自发消息决不注入
{
  mockStore.data.set('group:100:mid-1', {
    self: true,
    senderId: 'self',
    personaScope: 'scope:old-assistant', // Scope 不符
    text: '我是严肃助手'
  });
  const entries = [{
    senderId: '12345',
    directText: '你真逗',
    reply: { mid: 'mid-1' }
  }];
  const res = buildKnowledgeQueryContext({
    mode: 'linked-v1',
    owner: '12345',
    chatKey: 'group:100',
    entries,
    store: mockStore,
    roleScope: 'scope:hajimi'
  });
  assert.equal(res.linkedCount, 0, '非同 scope 历史自发消息不得混入');
}

// 反例 3：引用别人的发言不作为猫的父上下文
{
  mockStore.data.set('group:100:mid-2', {
    self: false, // 别人发的
    senderId: '67890',
    personaScope: 'scope:hajimi',
    text: '今晚吃啥'
  });
  const entries = [{
    senderId: '12345',
    directText: '哈哈',
    reply: { mid: 'mid-2' }
  }];
  const res = buildKnowledgeQueryContext({
    mode: 'linked-v1',
    owner: '12345',
    chatKey: 'group:100',
    entries,
    store: mockStore,
    roleScope: 'scope:hajimi'
  });
  assert.equal(res.linkedCount, 0, '他人发言不可作为检索父上下文');
}
